use std::fmt::Write as _;
use std::io::Write as _;
use std::process::ExitCode;

const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    let w = dims.width;
    let h = dims.height;
    if (x >= w || y >= h) {
        return;
    }
    let xl = select(x - 1u, x, x == 0u);
    let xr = select(x + 1u, x, x + 1u >= w);
    let yu = select(y - 1u, y, y == 0u);
    let yd = select(y + 1u, y, y + 1u >= h);
    let row = y * w;
    let c = src[row + x];
    let sum = 4u * c + src[row + xl] + src[row + xr] + src[yu * w + x] + src[yd * w + x];
    dst[row + x] = sum / 8u;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_whitespace();
    let mut next = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("unexpected end of input reading {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid {what}: {tok:?}"))
    };
    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) {
        return Err(format!("width {width} out of range 1..=512"));
    }
    if !(1..=512).contains(&height) {
        return Err(format!("height {height} out of range 1..=512"));
    }
    if steps > 1000 {
        return Err(format!("steps {steps} out of range 0..=1000"));
    }
    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for _ in 0..count {
        let v = next("cell")?;
        if v > 1_000_000 {
            return Err(format!("cell value {v} out of range 0..=1000000"));
        }
        cells.push(v as u32);
    }
    if tokens.next().is_some() {
        return Err("trailing data after grid".to_string());
    }
    Ok(Grid {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    pollster::block_on(run_gpu_async(grid))
}

async fn run_gpu_async(grid: &Grid) -> Result<Vec<u32>, String> {
    use wgpu::util::DeviceExt;

    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::default());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let byte_len = (grid.cells.len() * std::mem::size_of::<u32>()) as u64;

    let dims = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&[grid.width, grid.height]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("grid a"),
        contents: bytemuck::cast_slice(&grid.cells),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("grid b"),
        size: byte_len,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: byte_len,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: dims.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    // groups[i] reads from one buffer and writes the other; steps alternate.
    let groups = [make_group(&buf_a, &buf_b), make_group(&buf_b, &buf_a)];

    let gx = grid.width.div_ceil(WORKGROUP);
    let gy = grid.height.div_ceil(WORKGROUP);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    for step in 0..grid.steps {
        // A separate pass per step: wgpu inserts a barrier between passes, so
        // each step sees exactly what the previous step wrote.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[(step % 2) as usize], &[]);
        pass.dispatch_workgroups(gx, gy, 1);
    }
    let result = if grid.steps % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, byte_len);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback dropped: {e}"))?
        .map_err(|e| format!("cannot map readback buffer: {e}"))?;
    let out = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(out)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-heat <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("bad input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match run_gpu(&grid) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::FAILURE;
        }
    };

    let mut out = String::with_capacity(cells.len() * 8 + 32);
    let mut total: u64 = 0;
    for row in cells.chunks(grid.width as usize) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            let _ = write!(out, "{v}");
            total += u64::from(*v);
        }
        out.push('\n');
    }
    let _ = writeln!(out, "SUM {total}");
    let mut stdout = std::io::stdout().lock();
    if let Err(e) = stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()) {
        eprintln!("cannot write output: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

